var e={configTemplates:{intro:{t:0,b:{t:2,i:[{t:3}],s:`貼り付けてすぐ使える Klipper の設定ブロックとマクロ - 印刷開始シーケンス、フィラメント処理、入力シェーピング、ベッドメッシュなど。1つコピーして printer.cfg に貼り付けてください（設定エディターが貼り付け先として便利です）。`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`ヘルプ`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`設定テンプレートについて`}},close:{t:0,b:{t:2,i:[{t:3}],s:`閉じる`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`使い方`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`カテゴリーで絞り込んで、マクロや設定ブロックを探します。`}},{t:0,b:{t:2,i:[{t:3}],s:`説明と、必要なセクションを確認します。`}},{t:0,b:{t:2,i:[{t:3}],s:`テンプレートをコピーして設定に貼り付け、値を調整します。`}}],topics:{what:{title:{t:0,b:{t:2,i:[{t:3}],s:`これは何か`}},body:{t:0,b:{t:2,i:[{t:3}],s:`よく使う Klipper のビルディングブロックを厳選したセットです。gcode_macro（PRINT_START、PAUSE/RESUME、フィラメントのロード/アンロード、M600）と設定セクション（[input_shaper]、[bed_mesh]、[firmware_retraction] など）が含まれます。あくまで出発点なので、それぞれ内容を読んで自分のマシンに合わせて調整してください。`}}},insert:{title:{t:0,b:{t:2,i:[{t:3}],s:`テンプレートの挿入`}},body:{t:0,b:{t:2,i:[{t:3}],s:`テンプレートをコピーして printer.cfg に貼り付けます - 設定エディターの Raw ビューが手軽な貼り付け先です。保存後、ファームウェアの再起動で反映されます。値は必ず先に確認してください。ここでのデフォルトは妥当な値ですが、お使いのプリンターに合わせて調整されてはいません。`}}},sections:{title:{t:0,b:{t:2,i:[{t:3}],s:`必要なセクション`}},body:{t:0,b:{t:2,i:[{t:3}],s:`各テンプレートには、定義または依存する設定セクションが記載されています。すでに設定内に存在するセクションは、重複して貼り付けるのではなくキーをマージしてください（重複したセクションは起動時に拒否されます）。`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`用語集`}},body:{t:0,b:{static:``,t:2,i:[]}}}},glossary:{template:{term:{t:0,b:{t:2,i:[{t:3}],s:`テンプレート`}},def:{t:0,b:{t:2,i:[{t:3}],s:`printer.cfg にコピーして使う、すぐ貼り付けられる Klipper の設定やマクロ G-code のスニペットです。`}}},macro:{term:{t:0,b:{t:2,i:[{t:3}],s:`gcode_macro`}},def:{t:0,b:{t:2,i:[{t:3}],s:`設定内で定義する名前付きのコマンド（例：PRINT_START）で、一連の G-code を実行します。`}}},section:{term:{t:0,b:{t:2,i:[{t:3}],s:`セクション`}},def:{t:0,b:{t:2,i:[{t:3}],s:`[角括弧] で囲まれた設定ブロック（例：[bed_mesh]）で、Klipper の設定をまとめる単位です。`}}}}},category:{label:{t:0,b:{t:2,i:[{t:3}],s:`カテゴリー`}},all:{t:0,b:{t:2,i:[{t:3}],s:`すべてのカテゴリー`}}},template:{copy:{t:0,b:{t:2,i:[{t:3}],s:`コピー`}},copied:{t:0,b:{t:2,i:[{t:3}],s:`コピーしました！`}},requires:{t:0,b:{t:2,i:[{t:3,v:`セクション：`},{t:4,k:`sections`}]}},requiresNone:{t:0,b:{t:2,i:[{t:3}],s:`-`}}},count:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` 件のテンプレート`}]}},states:{loading:{t:0,b:{t:2,i:[{t:3}],s:`テンプレートを読み込み中…`}},error:{t:0,b:{t:2,i:[{t:3}],s:`テンプレートを読み込めませんでした。`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`このカテゴリーにテンプレートはありません。`}},retry:{t:0,b:{t:2,i:[{t:3}],s:`再試行`}}},categories:{config_blocks:{t:0,b:{t:2,i:[{t:3}],s:`設定ブロック`}},macros:{t:0,b:{t:2,i:[{t:3}],s:`マクロ`}}}}};export{e as default};